/// <summary>
/// Contains code for table AVAPurchAgreementLineTmp
/// </summary>
public class AVAPurchAgreementLineTmp extends common
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_agreementLine">_agreementLine</param>
public void initFromAgreementLine(AgreementLine _agreementLine)
{
    #AgreementsRemains
    container fulfillmentValues;
    AgreementLineQuantityCommitment agreementLineQuantityCommitment;
    AgreementLineVolumeCommitment   agreementLineVolumeCommitment;

    fulfillmentValues = AgreementLine::calculateFulfillmentForLine(_agreementLine);
    this.AgreementLineRecId = _agreementLine.RecId;
    this.RemainingReleasedQty = conPeek(fulfillmentValues, #RemainingIndex);
    this.RemainingDeliveredQty = conPeek(fulfillmentValues, #DeliveredNotInvoicedIndex);
    this.RemainingInvoicedQty = conPeek(fulfillmentValues, #InvoicedIndex);
    this.AgreementReleasedQty = conPeek(fulfillmentValues, #ReleasedNotInvoicedNorDeliveredIndex);

    if (_agreementLine.isQuantityBased())
    {
        agreementLineQuantityCommitment     = _agreementLine as AgreementLineQuantityCommitment;
        this.NetAmount                      = agreementLineQuantityCommitment.lineAmount();
        if(agreementLineQuantityCommitment.CommitedQuantity
            && _agreementLine.AVAMainPosition == NoYes::Yes)
        {
            this.RemainingReleasedPercentage    = roundDownDec(agreementLineQuantityCommitment.AVARestQtyCallOffItem / agreementLineQuantityCommitment.CommitedQuantity * 100, 2);
        }
        else if(agreementLineQuantityCommitment.CommitedQuantity)
        {
            this.RemainingReleasedPercentage    = roundDownDec(this.RemainingReleasedQty / agreementLineQuantityCommitment.CommitedQuantity * 100, 2);
        }
        else
        {
            this.RemainingReleasedPercentage    = 0.00;
        }
    }
    else
    {
        agreementLineVolumeCommitment = _agreementLine as AgreementLineVolumeCommitment;
        this.NetAmount = agreementLineVolumeCommitment.CommitedAmount;
    }

}
